const lockDueScheduledLegalVersion = `-- name: LockDueScheduledLegalVersion :one
SELECT v.id, v.document_id, v.locale, v.version, v.title, v.changelog, v.scheduled_at
FROM legal_document_version v
WHERE v.status = 'DRAFT' AND v.scheduled_at IS NOT NULL AND v.scheduled_at <= now()
ORDER BY v.scheduled_at ASC
FOR UPDATE SKIP LOCKED
LIMIT 1
`

type LockDueScheduledLegalVersionRow struct {
	ID          string           `json:"id"`
	DocumentID  string           `json:"document_id"`
	Locale      string           `json:"locale"`
	Version     string           `json:"version"`
	Title       string           `json:"title"`
	Changelog   pgtype.Text      `json:"changelog"`
	ScheduledAt pgtype.Timestamp `json:"scheduled_at"`
}

// Réclame UN brouillon arrivé à échéance, verrouillé jusqu'à la fin de la
// transaction : la publication et le déverrouillage sont donc atomiques, et
// deux workers ne peuvent pas publier la même version.
func (q *Queries) LockDueScheduledLegalVersion(ctx context.Context) (LockDueScheduledLegalVersionRow, error) {
	row := q.db.QueryRow(ctx, lockDueScheduledLegalVersion)
	var i LockDueScheduledLegalVersionRow
	err := row.Scan(
		&i.ID,
		&i.DocumentID,
		&i.Locale,
		&i.Version,
		&i.Title,
		&i.Changelog,
		&i.ScheduledAt,
	)
	return i, err
}

