const upsertLegalReview = `-- name: UpsertLegalReview :one

INSERT INTO legal_review (document_id, rule_key, due_at, status, notes)
VALUES (
    $1,
    $2,
    $3,
    'OPEN',
    $4
)
ON CONFLICT (document_id, rule_key, due_at) DO UPDATE
    SET updated_at = legal_review.updated_at
RETURNING id, document_id, rule_key, due_at, status, draft_version_id, notes, opened_at, completed_at, created_at, updated_at
`

type UpsertLegalReviewParams struct {
	DocumentID string           `json:"document_id"`
	RuleKey    string           `json:"rule_key"`
	DueAt      pgtype.Timestamp `json:"due_at"`
	Notes      pgtype.Text      `json:"notes"`
}

// ─── Revues périodiques ──────────────────────────────────────────────
// Ouvre (ou retrouve) la revue d'une échéance. `DO UPDATE` sans effet permet
// de récupérer la ligne existante : une même échéance n'ouvre qu'une revue,
// quel que soit le nombre de passages du worker.
func (q *Queries) UpsertLegalReview(ctx context.Context, arg UpsertLegalReviewParams) (LegalReview, error) {
	row := q.db.QueryRow(ctx, upsertLegalReview,
		arg.DocumentID,
		arg.RuleKey,
		arg.DueAt,
		arg.Notes,
	)
	var i LegalReview
	err := row.Scan(
		&i.ID,
		&i.DocumentID,
		&i.RuleKey,
		&i.DueAt,
		&i.Status,
		&i.DraftVersionID,
		&i.Notes,
		&i.OpenedAt,
		&i.CompletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
